 const raw=strFromU8(inner).replace(/\0/g,'');
 // Custom Quiz separates records with the byte-text delimiter >><<.
 // Splitting on <> alone incorrectly merges later questions into answer choices.
 const chunks=raw.split(/>><\</).filter(chunk=>chunk.trim());
 const questions=[];
 for(const chunk of chunks){
   const parts=chunk.split('<>');
   if(!parts.length) continue;
   const type=parts[0].trim();
   if(type==='multipleChoiceV2'||type.toLowerCase().includes('multiplechoice')){
     const q=(parts[1]||'').trim();
     const opts=parts.slice(3).map(s=>({raw:s.trim(),correct:s.trim().startsWith('C'),text:s.trim().replace(/^[CW]/,'').trim()})).filter(o=>o.text);
     if(!q||opts.length<2) continue;
     let answer=opts.findIndex(o=>o.correct);
     if(answer<0) answer=0;
     questions.push({question:q,options:opts.map(o=>o.text),answer,explanation:'Answer imported from the correct-answer marker stored in the .quiz file.'});
   }
 }
 if(!questions.length) throw new Error('No supported multiple-choice questions were found. This importer currently supports multipleChoiceV2 questions.');
