   const m=line.match(/^\s*(?:answer\s*key|answers|key)\s*[:\-]\s*(.*)$/i);
   if(m){for(const pair of m[1].matchAll(/(?:\b(\d{1,3})\s*[.)\-:]?\s*([A-D])\b)/gi))answerKey[Number(pair[1])]=pair[2].toUpperCase();}
