function QuizCard({quiz,i,onStart,onDelete,onEdit,onEditQuestions,onAIPrepare,aiBusy=false,aiProgress=null,selected=false,onToggleSelect}){const colors=['lavender','mint','peach','blueish'];return <article className={`quiz-card ${selected?'quiz-card-selected':''} ${quiz.cover?'has-cover':''}`} style={quiz.cover?{backgroundImage:'linear-gradient(180deg,#12182708 0%,#12182738 35%,#121827db 100%),url("'+quiz.cover+'")'}:undefined}><div className={`quiz-card-art ${colors[i%4]} ${quiz.cover?'has-cover-art':''}`}><div className="card-art-icon">{quiz.icon|| (i%3===0?<Brain size={24}/>:i%3===1?<BookOpen size={24}/>:<GraduationCap size={24}/>)}</div><span className="file-tag">QUIZ SET</span>{onToggleSelect&&<label className="quiz-select" title="Select quiz to combine"><input type="checkbox" checked={selected} onChange={onToggleSelect}/><span>Select</span></label>}<div className="quiz-card-actions"><button className="delete-btn edit-btn" title="Edit questions and answers" onClick={onEditQuestions}><PencilLine size={15}/></button><button className="delete-btn edit-btn" title="Rename or change icon" onClick={onEdit}><Settings2 size={15}/></button><button className="delete-btn" title="Delete quiz and saved progress" onClick={()=>onDelete()}><Trash2 size={15}/></button></div></div><div className="quiz-card-body"><h3>{quiz.title}</h3><p className="quiz-source">{quiz.source||'Imported quiz file'}</p><div className="quiz-meta"><span><ListChecks size={15}/>{quiz.questions.length} questions</span><span><Clock3 size={15}/>Self-paced</span></div><button className={`button subtle card-ai-prepare ${aiBusy&&aiProgress?.quizId===quiz.id?'is-ai-progress':''} ${quiz.questions.length>0&&quiz.questions.every(q=>q.aiPrepared)?'is-ai-validated':''}`} style={aiBusy&&aiProgress?.quizId===quiz.id?{'--ai-progress':`${Math.min(100,Math.round((aiProgress.completed/Math.max(1,aiProgress.total))*100))}%`}:undefined} onClick={onAIPrepare} disabled={aiBusy||(quiz.questions.length>0&&quiz.questions.every(q=>q.aiPrepared))} aria-label={quiz.questions.length>0&&quiz.questions.every(q=>q.aiPrepared)?'Quiz validated':aiBusy&&aiProgress?.quizId===quiz.id?`AI validation ${Math.round((aiProgress.completed/Math.max(1,aiProgress.total))*100)} percent complete`:'AI validate and explain'} title={quiz.questions.length>0&&quiz.questions.every(q=>q.aiPrepared)?'All questions are validated':navigator.onLine?'Generate and validate answers and explanations with AI':'AI preparation requires an internet connection'}><span className="ai-progress-fill"/><span className="ai-button-content">{quiz.questions.length>0&&quiz.questions.every(q=>q.aiPrepared)?<Check size={15}/>:<Sparkles size={15}/>}{aiBusy&&aiProgress?.quizId===quiz.id?`Validating ${aiProgress.completed}/${aiProgress.total}`:quiz.questions.length&&quiz.questions.every(q=>q.aiPrepared)?'Validated':'AI validate & explain'}</span></button><button className="button primary card-start" onClick={onStart}>Start practicing <ChevronRight size={16}/></button></div></article>}
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js', { updateViaCache: 'none' }).then((registration) => {
      // Check for a new app shell whenever REEQUIZ is opened online. The
      // service worker version changes whenever offline assets are updated.
      registration.update().catch(() => {});
    }).catch((error) => {
      console.warn('REEQUIZ offline support could not be registered:', error);
    });
  });
}

createRoot(document.getElementById('root')).render(<App/>);
